// Vergleicht installierte und verfuegbare n8n-Versionen (Semantic Versioning).
// Quelle: offizielle GitHub-Releases von n8n-io/n8n. Vorabversionen werden verworfen.
const status = $('Installierte Version ermitteln').first().json;
const installed = status.runningVersion || status.configuredVersion;
const SEMVER = /^(\d+)\.(\d+)\.(\d+)$/;
const parse = (v) => {
  const m = SEMVER.exec(v || '');
  if (!m) throw new Error('Ungueltige Version: ' + v);
  return m.slice(1).map(Number);
};
const cmp = (a, b) => {
  const x = parse(a), y = parse(b);
  for (let i = 0; i < 3; i++) if (x[i] !== y[i]) return x[i] - y[i];
  return 0;
};

const releases = $input.all().map((i) => i.json);
const stable = releases
  .filter((r) => !r.draft && !r.prerelease && /^n8n@\d+\.\d+\.\d+$/.test(r.tag_name || ''))
  .map((r) => ({ version: r.tag_name.slice(4), url: r.html_url, publishedAt: r.published_at, body: r.body || '' }))
  .sort((a, b) => cmp(b.version, a.version));
if (!stable.length) throw new Error('GitHub lieferte keine stabile n8n-Version');

const major = parse(installed)[0];
const latestOverall = stable[0];
const latestSameMajor = stable.find((r) => parse(r.version)[0] === major) || null;

let decision = 'none';
let reason = 'Installierte Version ' + installed + ' ist aktuell';
let target = null;
let release = null;

if (status.updateInProgress) {
  decision = 'skip';
  reason = 'Ein Update laeuft bereits';
} else if (status.configuredVersion !== status.runningVersion) {
  decision = 'blocked';
  reason = 'Konfigurierte (' + status.configuredVersion + ') und laufende (' + status.runningVersion + ') Version weichen ab';
} else if (latestSameMajor && cmp(latestSameMajor.version, installed) > 0) {
  target = latestSameMajor.version;
  release = latestSameMajor;
  if (/breaking change/i.test(release.body)) {
    decision = 'manual';
    reason = 'Release Notes von ' + target + ' melden Breaking Changes - manuelles Update erforderlich';
  } else {
    decision = 'update';
    reason = 'Neue stabile Version ' + target + ' verfuegbar';
  }
} else if (cmp(latestOverall.version, installed) > 0) {
  target = latestOverall.version;
  release = latestOverall;
  decision = 'manual';
  reason = 'Neue Major-Version ' + target + ' verfuegbar - manuelles Update erforderlich';
}

return [{ json: {
  checkedAt: new Date().toISOString(),
  installedVersion: installed,
  availableVersion: latestOverall.version,
  latestSameMajor: latestSameMajor ? latestSameMajor.version : null,
  targetVersion: target,
  decision,
  reason,
  releaseUrl: release ? release.url : latestOverall.url,
  releasePublishedAt: release ? release.publishedAt : latestOverall.publishedAt,
  releaseNotesExcerpt: release ? release.body.slice(0, 1500) : '',
  lastUpdateStatus: status.lastUpdate ? status.lastUpdate.status + ' ' + (status.lastUpdate.targetVersion || '') : 'none',
  stableVersionsSeen: stable.slice(0, 10).map((r) => r.version),
} }];

// GitHub-Abfrage fehlgeschlagen: Fehler protokollieren, kein Update.
const clean = (s) => String(s ?? '').replace(/[^\p{L}\p{N}_ .,:;\/@()+#=?&%-]/gu, ' ').slice(0, 300);
const status = $('Installierte Version ermitteln').first().json;
const err = $input.first().json.error || $input.first().json;
return [{ json: {
  checkedAt: new Date().toISOString(),
  trigger: $('Montag 03:00 (Europe/Berlin)').isExecuted ? 'schedule' : 'manual',
  executionId: String($execution.id),
  installedVersion: status.runningVersion || status.configuredVersion,
  decision: 'error',
  reason: 'Versionsabfrage bei GitHub fehlgeschlagen',
  updateRequested: false,
  error: clean(typeof err === 'string' ? err : (err.message || JSON.stringify(err))),
} }];

// Fasst das Ergebnis aller Pfade zu einem Protokolleintrag zusammen.
const clean = (s) => String(s ?? '').replace(/[^\p{L}\p{N}_ .,:;\/@()+#=?&%-]/gu, ' ').slice(0, 300);
const cmp = $('Versionen vergleichen').first().json;
let decision = cmp.decision;
let reason = cmp.reason;
let updateRequested = false;
let error = '';

if ($('Vorabpruefung (Dry-Run)').isExecuted) {
  const pf = $('Vorabpruefung (Dry-Run)').first().json;
  const body = pf.body || {};
  if (pf.statusCode !== 200 || body.ok !== true) {
    decision = 'blocked';
    reason = 'Vorabpruefung fehlgeschlagen: ' + ((body.failed || []).join(', ') || body.error || ('HTTP ' + pf.statusCode));
  }
}
if ($('Update beim Host-Updater anfordern').isExecuted) {
  const r = $('Update beim Host-Updater anfordern').first().json;
  const body = r.body || {};
  if (r.statusCode === 202 && body.accepted === true) {
    updateRequested = true;
    reason = 'Update auf ' + body.targetVersion + ' angenommen (requestId ' + body.requestId + '). Backup, Installation, Healthchecks und ggf. Rollback laufen auf dem Host.';
  } else {
    decision = 'error';
    error = 'Updater HTTP ' + r.statusCode + ': ' + JSON.stringify(body);
  }
}

return [{ json: {
  checkedAt: cmp.checkedAt,
  trigger: $('Montag 03:00 (Europe/Berlin)').isExecuted ? 'schedule' : 'manual',
  executionId: String($execution.id),
  installedVersion: cmp.installedVersion,
  availableVersion: cmp.availableVersion,
  targetVersion: cmp.targetVersion || '',
  decision,
  reason: clean(reason),
  updateRequested,
  error: clean(error),
  releaseUrl: clean(cmp.releaseUrl),
  lastUpdateStatus: clean(cmp.lastUpdateStatus),
} }];
